def _mutable_container_copy(value):
    \"\"\"Return an empty same-class copy for containers that can be filled in place.\"\"\"
    if not isinstance(value, (MutableMapping, MutableSequence, MutableSet)):
        return None

    try:
        result = copy.copy(value)
        if result is value:
            result = type(value)()
        result.clear()
        return result
    except (AttributeError, TypeError):
        try:
            return type(value)()
        except (TypeError, ValueError):
            return None


def _rebuild_redaction_container(value, items):
    \"\"\"Rebuild an immutable container from transformed members.\"\"\"
    if isinstance(value, Mapping):
        try:
            return type(value)(items)
        except (TypeError, ValueError):
            return type(value)(dict(items))
    if isinstance(value, tuple):
        if type(value) is tuple:
            return tuple(items)
        try:
            return type(value)(*items)
        except TypeError:
            return type(value)(items)
    if isinstance(value, Set):
