        return type(value)(items)
    except (TypeError, ValueError):
        return tuple(items)


def _transform_redaction_data(obj, no_log_strings, key_transform=None):
    \"\"\"Copy and transform supported containers using an explicit work stack.\"\"\"
    transformed = {}
    active = set()
    pending = [('visit', obj)]

    while pending:
        action, value = pending.pop()
        value_id = id(value)

        if action == 'visit':
            if isinstance(value, (text_type, binary_type)):
                transformed[value_id] = _redact_string(value, no_log_strings)
                continue
            if not _is_redaction_container(value) or value_id in transformed or value_id in active:
                continue

            active.add(value_id)
            shell = _mutable_container_copy(value)
            if shell is not None:
                transformed[value_id] = shell
            pending.append(('build', value))

            children = list(value.values()) if isinstance(value, Mapping) else list(value)
            for child in reversed(children):
                if id(child) not in transformed:
                    pending.append(('visit', child))
            continue

        if isinstance(value, Mapping):
            items = []
            for old_key, old_item in value.items():
                new_key = key_transform(old_key) if key_transform else old_key
                items.append((new_key, transformed.get(id(old_item), old_item)))
            result = transformed.get(value_id)
            if result is not None:
                result.update(items)
            else:
                transformed[value_id] = _rebuild_redaction_container(value, items)
        elif isinstance(value, (MutableSequence, MutableSet)):
            result = transformed[value_id]
            items = [transformed.get(id(item), item) for item in value]
            if isinstance(result, MutableSequence):
                result.extend(items)
            else:
                result.update(items)
        else:
            items = [transformed.get(id(item), item) for item in value]
            transformed[value_id] = _rebuild_redaction_container(value, items)

        active.discard(value_id)

    return transformed.get(id(obj), obj)


def remove_values(value, no_log_strings):
    \"\"\"Return a type-preserving copy with sensitive substrings removed from values.\"\"\"
    return _transform_redaction_data(value, _native_no_log_strings(no_log_strings))


def sanitize_keys(obj, no_log_strings, ignore_keys=frozenset()):
    \"\"\"Return a copy with sensitive substrings removed from mapping keys.

    Mapping values are traversed without recursion, including mappings nested
    inside sequences and sets. Non-mapping data is otherwise left untouched.
    \"\"\"
    no_log_strings = _native_no_log_strings(no_log_strings)
    ignored_keys = set(
        to_native(key, encoding='utf-8', errors='surrogate_or_replace')
        for key in ignore_keys
    )

    def redact_key(key):
        if not isinstance(key, (text_type, binary_type)):
            return key
        native_key = to_native(key, encoding='utf-8', errors='surrogate_or_replace')
        if native_key in ignored_keys or native_key.startswith('_ansible'):
            return key
        if native_key in no_log_strings:
            return 'VALUE_SPECIFIED_IN_NO_LOG_PARAMETER'
        return _redact_string(key, no_log_strings)

    result = _transform_redaction_data(obj, (), key_transform=redact_key)
    if not isinstance(obj, Mapping):
        # Lists, tuples, and sets without mappings contain nothing to sanitize.
        pending = [obj]
        seen = set()
        contains_mapping = False
        while pending:
            current = pending.pop()
            current_id = id(current)
            if current_id in seen:
                continue
            seen.add(current_id)
            if isinstance(current, Mapping):
                contains_mapping = True
                break
            if _is_redaction_container(current):
                pending.extend(current.values() if isinstance(current, Mapping) else current)
        if not contains_mapping:
            return obj
    return result


